-- when fire, the rewrite.  001: the tables.  Sunday, October 25, 2026.
-- One schema holds the record, the graph, the shelf and the bus.  Every row has an owner.
-- Nothing in the record is edited or deleted; a later row supersedes, corrects, replaces or negates an earlier one.
-- Derived rows (fires, episodes, snapshots, costs) are regenerated by replay and may be dropped.
-- Words: see docs/rewrite_brief_2026-10-25.md, section 3.  Capitals for actors in prose; snake_case in code.

create extension if not exists vector with schema extensions;
create extension if not exists pgcrypto with schema extensions;

create schema if not exists when_fire;

-- ---------------------------------------------------------------------------------------------
-- People.  Owners.  The system itself is a person of kind 'system' and owns the shared rows.
-- ---------------------------------------------------------------------------------------------
create table when_fire.people (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  kind        text not null default 'person' check (kind in ('person', 'system')),
  name        text not null,
  words       text,                      -- how the person is introduced to a model, in his own words
  tz          text not null default 'UTC',
  auth_user   uuid,                      -- the Supabase auth user, when the person signs in (later)
  token_hash  text unique,               -- sha256 of the connector token that names this person
  shape       jsonb
);
comment on table when_fire.people is 'Owners.  Every other row points here.  kind system is the system itself, owner of the shared concepts and settings.';

create or replace function when_fire.system_id() returns uuid language sql immutable set search_path = pg_catalog
  as $$ select '00000000-0000-4000-8000-000000000001'::uuid $$;

-- ---------------------------------------------------------------------------------------------
-- Settings and caps.  Per owner; the system's row is the default.
-- ---------------------------------------------------------------------------------------------
create table when_fire.settings (
  owner  uuid not null references when_fire.people(id),
  key    text not null,
  value  text not null,
  note   text,
  primary key (owner, key)
);
comment on table when_fire.settings is 'Knobs.  An owner''s value wins over the system''s.  Not part of the record; may be edited.';

create table when_fire.caps (
  owner  uuid not null references when_fire.people(id),
  actor  text not null default '*',       -- '*' covers every actor
  name   text not null,                   -- daily_dollars, max_rounds, max_tokens, hours
  value  text not null,
  note   text,
  primary key (owner, actor, name)
);
comment on table when_fire.caps is 'The seatbelt: one row per cap.  An owner''s caps are his seatbelt; actor * covers every actor.';

-- ---------------------------------------------------------------------------------------------
-- The record: whens, facts, fires.
-- ---------------------------------------------------------------------------------------------
create table when_fire.whens (
  id               uuid primary key default gen_random_uuid(),
  owner            uuid not null references when_fire.people(id),
  asserted_at      timestamptz not null default now(),
  asserted_by      text not null,         -- 'stacy' for the person's side; an actor's name for the system's side
  words            text not null,         -- the thing, as spoken
  condition_words  text,                  -- the when, as spoken
  condition        jsonb,                 -- machine form; null means worded (judged by the Watch)
  kind             text not null check (kind in ('tick', 'after', 'quiet', 'on', 'worded')),
  handler          text,                  -- kind on: the handler the fire is dispatched to
  bounds           jsonb,                 -- what the handler may not do
  bundle           uuid references when_fire.whens(id),
  until_words      text,
  until_at         timestamptz,           -- the horizon, in machine form; null means none named
  supersedes       uuid references when_fire.whens(id),
  shape            jsonb
);
comment on table when_fire.whens is 'What the person or the system said will happen or be done, with the condition that makes it due.  Append-only; a later when supersedes an earlier one.';
comment on column when_fire.whens.kind is 'tick: a clock.  after: a fact landing.  quiet: a gap.  on: another when''s fire (a listener).  worded: judged by the Watch from the words.';
create index whens_owner_idx on when_fire.whens (owner);
create index whens_supersedes_idx on when_fire.whens (supersedes);
create index whens_bundle_idx on when_fire.whens (bundle);

create table when_fire.sources (
  id           uuid primary key default gen_random_uuid(),
  owner        uuid not null references when_fire.people(id),
  captured_at  timestamptz not null default now(),
  happened_at  timestamptz,               -- the source's own date: the visit, the draw, the day written, the picture taken
  origin       text not null,             -- who or where it came from, in words
  kind         text,                      -- what it is, in a few words; never a fixed list
  title        text,
  text         text,                      -- the whole text, when there is text
  media_path   text,                      -- a picture or a recording in the private bucket, when there is one
  media_type   text,
  shape        jsonb
);
comment on table when_fire.sources is 'A record that identifies a document, says what it is, and says where to find it.  Whole, never changed.  A picture or a recording is a source too.';
create index sources_owner_idx on when_fire.sources (owner);

create table when_fire.facts (
  id           uuid primary key default gen_random_uuid(),
  owner        uuid not null references when_fire.people(id),
  happened_at  timestamptz not null default now(),   -- valid time: when it happened in the world
  recorded_at  timestamptz not null default now(),   -- transaction time: when the record found out
  said_by      text not null,             -- who said it: the person, a device, an actor
  kind         text not null default 'world' check (kind in ('world', 'note')),
  said         text not null,             -- the words
  about        uuid references when_fire.whens(id),  -- the when the person named, if he named one
  corrects     uuid references when_fire.facts(id),
  cites        uuid references when_fire.sources(id),  -- the picture or recording this fact was read from
  shape        jsonb
);
comment on table when_fire.facts is 'What happened, in words, with two times.  kind world is the person''s life; kind note is the system''s own footnote and is never evidence that the person did a thing.';
create index facts_owner_recorded_idx on when_fire.facts (owner, recorded_at);
create index facts_owner_happened_idx on when_fire.facts (owner, happened_at);
create index facts_about_idx on when_fire.facts (about);

create table when_fire.fires (
  id        uuid primary key default gen_random_uuid(),
  owner     uuid not null references when_fire.people(id),
  when_id   uuid not null references when_fire.whens(id),
  fired_at  timestamptz not null default now(),
  kind      text not null check (kind in ('tick', 'met', 'silence', 'land', 'quiet', 'heard')),
  fired_by  text not null,                -- heartbeat, landing, listener, watch, or a person
  by_fact   uuid references when_fire.facts(id),
  by_fire   uuid references when_fire.fires(id),
  context   jsonb
);
comment on table when_fire.fires is 'A when coming true.  tick: its clock.  met and silence: the Watch''s readings.  land: a fact landed.  quiet: a gap passed.  heard: a listener heard its when fire.';
create index fires_owner_fired_idx on when_fire.fires (owner, fired_at);
create index fires_when_idx on when_fire.fires (when_id, fired_at);
create index fires_by_fire_idx on when_fire.fires (by_fire);

-- ---------------------------------------------------------------------------------------------
-- The graph: concepts and links.  Reason is a kind of concept.
-- ---------------------------------------------------------------------------------------------
create table when_fire.relations (
  name        text primary key,          -- kind_of, part_of, works, opposes, because, about, same_as
  inverse     text,
  note        text,
  created_by  text not null default 'seed',
  created_at  timestamptz not null default now(),
  admitted    boolean not null default true   -- a word the glance proposed waits here until a person admits it
);
comment on table when_fire.relations is 'The short list of relation words a link may carry.  The glance picks from it and may propose a new one, which a person admits.';

create table when_fire.concepts (
  id          uuid primary key default gen_random_uuid(),
  owner       uuid not null references when_fire.people(id),   -- the system owns the shared ones
  created_at  timestamptz not null default now(),
  created_by  text not null,              -- seed, glance, reconciler, librarian, or a person
  kind        text not null,              -- body_part, movement, measure, reason, person, place, goal, document, substance, condition
  name        text not null,              -- one lowercase name
  words       text,                       -- the person's words, when the concept came from them (a reason, say)
  supersedes  uuid references when_fire.concepts(id),
  shape       jsonb
);
comment on table when_fire.concepts is 'A meaning in the graph.  Shared concepts (body parts, movements, measures) are owned by the system and read by every owner; the rest are the owner''s own.';
create unique index concepts_owner_kind_name_idx on when_fire.concepts (owner, kind, name) where supersedes is null;
create index concepts_name_idx on when_fire.concepts (lower(name));

create table when_fire.links (
  id          uuid primary key default gen_random_uuid(),
  owner       uuid not null references when_fire.people(id),
  created_at  timestamptz not null default now(),
  created_by  text not null,              -- provenance: seed, glance, reconciler, librarian, stacy, model
  from_kind   text not null check (from_kind in ('concept', 'fact', 'when', 'claim', 'source', 'question')),
  from_id     uuid not null,
  relation    text not null references when_fire.relations(name),
  to_concept  uuid not null references when_fire.concepts(id),
  cites       text,                       -- what the link rests on: a claim id, a fact id, or words
  negates     uuid references when_fire.links(id),   -- an unlink is a later row
  shape       jsonb
);
comment on table when_fire.links is 'A named relation from a concept, fact, when, claim, source or question to a concept.  Walks follow these.  A wrong link is negated by a later row, never deleted.';
create index links_from_idx on when_fire.links (from_kind, from_id);
create index links_to_idx on when_fire.links (to_concept, relation);
create index links_owner_idx on when_fire.links (owner);

-- ---------------------------------------------------------------------------------------------
-- Bridges: what a fact counts toward.  One fact, one row, forever; bridges carry the counting.
-- ---------------------------------------------------------------------------------------------
create table when_fire.bridges (
  id          uuid primary key default gen_random_uuid(),
  owner       uuid not null references when_fire.people(id),
  created_at  timestamptz not null default now(),
  made_by     text not null,              -- stated, rule, reconciler, model
  fact_id     uuid not null references when_fire.facts(id),
  when_id     uuid not null references when_fire.whens(id),
  amount      numeric,                    -- what this fact contributes to this when's tally, when a number applies
  cites       text,                       -- the link or claim that justifies it, or words
  negates     uuid references when_fire.bridges(id),
  shape       jsonb
);
comment on table when_fire.bridges is 'A fact counting toward a when.  Tallies are per when and never sum across whens, so nothing is counted twice.';
create index bridges_when_idx on when_fire.bridges (when_id);
create index bridges_fact_idx on when_fire.bridges (fact_id);

-- ---------------------------------------------------------------------------------------------
-- Episodes and snapshots.  Derived; regenerated by replay.
-- ---------------------------------------------------------------------------------------------
create table when_fire.episodes (
  id          uuid primary key default gen_random_uuid(),
  owner       uuid not null references when_fire.people(id),
  kind        text not null check (kind in ('episode', 'day')),
  first_at    timestamptz not null,       -- happened time of the first world fact
  last_at     timestamptz not null,       -- happened time of the last world fact so far
  closed_at   timestamptz,                -- when the Reconciler closed it; null while open
  day         date,                       -- local date, kind day
  shape       jsonb
);
comment on table when_fire.episodes is 'A stretch of activity closed by a gap, in the person''s happened time.  A day is the episode closed by sleep (or the long gap, or the backstop hour).';
create index episodes_owner_idx on when_fire.episodes (owner, first_at);

create table when_fire.snapshots (
  id            uuid primary key default gen_random_uuid(),
  owner         uuid not null references when_fire.people(id),
  subject_kind  text not null check (subject_kind in ('when', 'bundle', 'episode', 'day', 'concept', 'question', 'system')),
  subject_id    uuid,                     -- null for the system
  watermark     timestamptz not null,     -- recorded time up to which this snapshot is complete
  written_at    timestamptz not null default now(),
  written_by    text not null,            -- reconciler, replay
  says          text not null,            -- what stands now, in words
  replaces      uuid references when_fire.snapshots(id),
  shape         jsonb                     -- cites: fact ids, fire ids; tallies
);
comment on table when_fire.snapshots is 'What stands now about a subject, as of a watermark, replacing an earlier snapshot.  Never edited; the current one is the one nothing replaces.';
create index snapshots_subject_idx on when_fire.snapshots (subject_kind, subject_id, written_at);
create index snapshots_replaces_idx on when_fire.snapshots (replaces);

create view when_fire.current_snapshots as
  select s.* from when_fire.snapshots s
  where not exists (select 1 from when_fire.snapshots r where r.replaces = s.id);

-- ---------------------------------------------------------------------------------------------
-- Questions: what the Thinker wants to know.  Standing things, not messages.
-- ---------------------------------------------------------------------------------------------
create table when_fire.questions (
  id          uuid primary key default gen_random_uuid(),
  owner       uuid not null references when_fire.people(id),
  asked_at    timestamptz not null default now(),
  asked_by    text not null,              -- thinker, or a person
  words       text not null,
  about_kind  text,                       -- when, concept, fact, bundle
  about_id    uuid,
  ask_of      text not null default 'shelf',   -- where the Thinker is looking now: shelf, record, health, facts, person
  shape       jsonb
);
comment on table when_fire.questions is 'Something the Thinker wants to know.  Open until an event answers it; asked of the shelf, the record, Health, several facts over days, and the person last.';

create table when_fire.question_events (
  id           uuid primary key default gen_random_uuid(),
  question_id  uuid not null references when_fire.questions(id),
  at           timestamptz not null default now(),
  kind         text not null check (kind in ('asked', 'tried', 'answered', 'dropped', 'sent')),
  by           text not null,
  words        text,
  cites        text,                      -- the fact or claim that answered, when one did
  shape        jsonb
);
create index question_events_q_idx on when_fire.question_events (question_id, at);

create view when_fire.open_questions as
  select q.* from when_fire.questions q
  where not exists (select 1 from when_fire.question_events e where e.question_id = q.id and e.kind in ('answered', 'dropped'));

-- ---------------------------------------------------------------------------------------------
-- Costs: a footnote on every model call.
-- ---------------------------------------------------------------------------------------------
create table when_fire.costs (
  id               uuid primary key default gen_random_uuid(),
  owner            uuid not null references when_fire.people(id),
  at               timestamptz not null default now(),
  actor            text not null,
  model            text not null,
  tokens_in        integer not null default 0,
  tokens_out       integer not null default 0,
  tokens_thinking  integer not null default 0,
  tokens_cached    integer not null default 0,
  dollars          numeric(10, 6) not null default 0,
  stop_reason      text,
  seconds          numeric(8, 2),
  fire_id          uuid references when_fire.fires(id),
  note             text
);
create index costs_owner_at_idx on when_fire.costs (owner, at);

-- ---------------------------------------------------------------------------------------------
-- The outbox: tasks for the Doer, written before they are done.
-- ---------------------------------------------------------------------------------------------
create table when_fire.tasks (
  id          uuid primary key default gen_random_uuid(),
  owner       uuid not null references when_fire.people(id),
  created_at  timestamptz not null default now(),
  created_by  text not null,
  kind        text not null,              -- morning_page, question, copy, mail, calendar, note
  words       text not null,
  due_at      timestamptz,
  fire_id     uuid references when_fire.fires(id),
  shape       jsonb
);
create table when_fire.task_events (
  id        uuid primary key default gen_random_uuid(),
  task_id   uuid not null references when_fire.tasks(id),
  at        timestamptz not null default now(),
  kind      text not null check (kind in ('requested', 'taken', 'done', 'error', 'dropped')),
  by        text not null,
  words     text,
  shape     jsonb
);
create index task_events_task_idx on when_fire.task_events (task_id, at);

create view when_fire.open_tasks as
  select t.* from when_fire.tasks t
  where not exists (select 1 from when_fire.task_events e where e.task_id = t.id and e.kind in ('done', 'dropped'));

-- ---------------------------------------------------------------------------------------------
-- Handlers: where the bus sends each fire that names one.
-- ---------------------------------------------------------------------------------------------
create table when_fire.handlers (
  name     text primary key,
  address  text not null,                 -- the function's URL
  note     text,
  enabled  boolean not null default true
);

-- ---------------------------------------------------------------------------------------------
-- The shelf: claims, one sentence each, cited to a source.  The embedding sits beside the claim.
-- ---------------------------------------------------------------------------------------------
create table when_fire.claims (
  id           uuid primary key default gen_random_uuid(),
  owner        uuid not null references when_fire.people(id),
  made_at      timestamptz not null default now(),
  made_by      text not null,             -- librarian, or a person
  source_id    uuid not null references when_fire.sources(id),
  said         text not null,
  about_words  text,
  supersedes   uuid references when_fire.claims(id),
  embedding    extensions.vector(384),
  tsv          tsvector generated always as (to_tsvector('english', coalesce(said, '') || ' ' || coalesce(about_words, ''))) stored,
  shape        jsonb
);
comment on table when_fire.claims is 'One sentence a source says, cited to it.  Append-only; a newer claim supersedes an older one and says so.';
create index claims_owner_idx on when_fire.claims (owner);
create index claims_source_idx on when_fire.claims (source_id);
create index claims_tsv_idx on when_fire.claims using gin (tsv);
create index claims_embedding_idx on when_fire.claims using hnsw (embedding extensions.vector_cosine_ops);

-- ---------------------------------------------------------------------------------------------
-- Row-level security on every table, from the first migration.  The API roles see nothing until a
-- policy names them; the one policy below lets a signed-in person see his own rows.  The actors reach
-- the tables through the doors, as the database owner.
-- ---------------------------------------------------------------------------------------------
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'when_fire' loop
    execute format('alter table when_fire.%I enable row level security', t);
  end loop;
end $$;

create or replace function when_fire.me() returns uuid language sql stable security definer
  set search_path = when_fire, pg_catalog, pg_temp
  as $$ select id from when_fire.people where auth_user = auth.uid() limit 1 $$;

do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'when_fire'
           and tablename not in ('people', 'relations', 'handlers', 'question_events', 'task_events') loop
    execute format('create policy own_rows on when_fire.%I for select to authenticated using (owner = when_fire.me() or owner = when_fire.system_id())', t);
  end loop;
end $$;
create policy own_rows on when_fire.relations for select to authenticated using (true);
create policy own_rows on when_fire.people for select to authenticated using (id = when_fire.me() or id = when_fire.system_id());
create policy own_rows on when_fire.question_events for select to authenticated
  using (exists (select 1 from when_fire.questions q where q.id = question_id and q.owner = when_fire.me()));
create policy own_rows on when_fire.task_events for select to authenticated
  using (exists (select 1 from when_fire.tasks t where t.id = task_id and t.owner = when_fire.me()));

-- ---------------------------------------------------------------------------------------------
-- Active whens: not superseded, horizon not passed.
-- ---------------------------------------------------------------------------------------------
create view when_fire.active_whens as
  select w.* from when_fire.whens w
  where not exists (select 1 from when_fire.whens s where s.supersedes = w.id)
    and (w.until_at is null or w.until_at > now());
